def resolve_settings(run, workspace, overrides=None):
    """설정 파일을 낮은 층부터 읽어 키마다 어느 층의 값이 적용됐는지 남긴다."""
    stacks = {
        key: [{"layer": "default", "value": value}]
        for key, value in default_settings().items()
    }
    files = []
    for layer, relative in (
        ("user", f"{USER_LAYER}/{SETTINGS_FILE}"),
        ("project", SETTINGS_FILE),
    ):
        text = read_traced(
            run,
            workspace_path(workspace, relative),
            "context",
            reason=f"{layer} 층의 설정 파일을 찾습니다. 없으면 이 층은 건너뜁니다.",
            required=False,
        )
        files.append({"layer": layer, "path": relative, "found": bool(text.strip())})
        if text.strip():
            for key, value in flatten_settings(json.loads(text), relative).items():
                stacks[key].append({"layer": layer, "path": relative, "value": value})
    for key, (layer, value) in (overrides or {}).items():
        stacks[key].append({"layer": layer, "value": checked_setting(key, value, layer)})
    run.settings = {key: stack[-1]["value"] for key, stack in stacks.items()}
    run.emit(
        "config.resolve",
        "설정 파일 계층에서 값 결정",
        "코드 기본값 위에 사용자 층과 프로젝트 층을 차례로 덮어씁니다. 나중 층의 값이 이깁니다. 모델은 이 결정에 참여하지 않습니다.",
        category="context",
        input={"order": ["default", "user", "project", "mode"], "files": files},
        output={
            "settings": [
                {
                    "key": key,
                    "value": stack[-1]["value"],
                    "source": stack[-1].get("path") or stack[-1]["layer"],
                    "layer": stack[-1]["layer"],
                    "layers": stack,
                }
                for key, stack in stacks.items()
            ]
        },
    )
    return run.settings

def discover_rules(run, workspace):
    names = effective_settings(run)["rules.file_names"]
    layers = (("user", f"{USER_LAYER}/"), ("project", ""))
    run.emit(
        "function.enter",
        "프로젝트 규칙 로더 호출",
        "build_context()가 discover_rules()를 호출했습니다. 모델의 판단 없이 하네스 코드가 실행합니다.",
        category="rules",
        input={
            "workspace": str(workspace),
            "candidates": [prefix + name for _, prefix in layers for name in names],
        },
    )
    found = []
    for scope, prefix in layers:
        for name in names:
            relative = prefix + name
            text = read_traced(
                run,
                workspace_path(workspace, relative),
                "rules",
                reason="설정된 후보 이름을 작업 공간 경로와 결합했습니다.",
                required=False,
            )
            if text.strip():
                found.append((scope, relative, text))
                break
    layered = len(found) > 1
    blocks = []
    for precedence, (scope, relative, text) in enumerate(found, 1):
        wrapped = (
            rule_block(relative, text, scope, precedence)
            if layered
            else rule_block(relative, text)
        )
        run.emit(
            "rules.wrap",
            "원문을 프로젝트 지침 블록으로 구성",
            "읽은 규칙의 본문은 유지하고 출처·경계 표시를 추가합니다. system 메시지에 포함할 블록입니다.",
            category="rules",
            input={"raw_text": text},
            output={"instruction_block": wrapped},
        )
        blocks.append(wrapped)
    conflict = (
        "\nIf project_rules blocks conflict, follow the block with the higher precedence number.\n"
        if layered
        else ""
    )
    run.emit(
        "rules.resolve",
        "규칙 파일의 적용 순서 결정",
        "사용자 층, 프로젝트 층 순서로 system 메시지에 넣고 번호가 큰 쪽을 따르라고 안내합니다. 코드는 순서와 안내만 정하며 모델이 실제로 따르는지는 강제하지 않습니다.",
        category="rules",
        output={
            "order": [
                {"precedence": index, "scope": scope, "source": relative}
                for index, (scope, relative, _) in enumerate(found, 1)
            ],
            "conflict_instruction": conflict.strip() or None,
            "directory_rules": "파일 도구가 하위 폴더를 건드릴 때 그 폴더의 규칙을 추가합니다.",
        },
    )
    return conflict + "".join(blocks)

def generate(run, runtime, payload, iteration):
    if hasattr(runtime, "generate_observed"):
        return runtime.generate_observed(run, payload, iteration)
    if hasattr(runtime, "stream_json"):
        run.emit(
            "http.inference.send",
            "실제 생성 HTTP 요청 시작",
            "이제 진단 API가 아니라 /v1/chat/completions로 POST합니다. 응답 미디어 타입과 계산 결과는 이후 이벤트에 기록합니다.",
            category="model",
            output={
                "call": iteration,
                "url": runtime.base_url + "/v1/chat/completions",
                "body_bytes": len(json.dumps(payload).encode("utf-8")),
            },
        )
    if not hasattr(runtime, "stream_json") or not payload.get("stream"):
        result = runtime.request("/v1/chat/completions", payload)
        if hasattr(runtime, "last_http"):
            run.emit(
                "http.inference.json",
                "실행기의 전체 JSON 응답 수신",
                "실제 HTTP 응답 상태와 Content-Type입니다. 이 방식은 생성 중간 조각이 아니라 완료된 응답을 한 번 받습니다.",
                category="model",
                actor="runtime",
                output={"call": iteration, **runtime.last_http},
            )
        probabilities = result.get("choices", [{}])[0].get("logprobs") or {}
        if probabilities.get("content"):
            native = result.get("__verbose") or {}
            run.emit(
                "model.decode.report",
                "전체 응답에서 생성 토큰·후보 확률 관측",
                "하나의 실제 JSON 응답에서 생성 관측값을 꺼낸 것입니다. 생성이 이 이벤트 시각에 토큰마다 진행된 것처럼 재구성하지 않습니다. 다음 단계에서 역할·도구 메시지를 사용합니다.",
                category="model",
                actor="llm",
                output={
                    "call": iteration,
                    "logprobs": probabilities,
                    "tokens": native.get("tokens"),
                    "usage": result.get("usage"),
                    "timings": result.get("timings"),
                    "generation_settings": native.get("generation_settings"),
                },
            )
        return result
    assembly = ChatAssembly()
    pause_at_start = run.paused_seconds
    try:
        _consume_stream(run, runtime, payload, iteration, assembly, pause_at_start)
    except Exception as error:
        # 스트림이 중간에 실패해도 그 시점까지 합친 메시지·도구 조각을 남긴다. 성공한 응답처럼 쓰지는 않는다.
        if assembly.frames:
            run.record_interrupted(
                "model.stream.partial",
                "스트림 실패 시점까지 합친 부분 응답",
                "스트림이 끝나기 전에 오류가 났습니다. 지금까지 받은 조각을 합친 상태이며 모델의 최종 응답이 아닙니다.",
                category="model",
                output={
                    "call": iteration,
                    "error": str(error),
                    "frames": assembly.frames,
                    "message_so_far": assembly.message,
                    "tool_calls_so_far": [assembly.calls[i] for i in sorted(assembly.calls)],
                    "finish_reason": assembly.finish,
                },
            )
        raise
    response = assembly.response()
    response["_assembly"]["pause_during_stream_seconds"] = round(
        run.paused_seconds - pause_at_start, 3
    )
    run.emit(
        "model.stream.assemble",
        "전송 조각을 모델 메시지·도구 요청으로 복원",
        "content는 문자열 조각을 순서대로 합치고 tool_calls는 index별로 id·이름·인자를 복원했습니다. 이 객체는 하네스가 원본 SSE를 합친 결과입니다.",
        category="model",
        output={
            "call": iteration,
            "message": response["choices"][0]["message"],
            "assembly": response["_assembly"],
        },
    )
    return response

def prepare_mcp(run, config):
    client = client_for(config, "mcp")
    client.start(run)
    try:
        info = client.request(run, "server/discover", mcp_params(client))
        client.legacy_mcp = False
        if MCP_VERSION not in info.get("supportedVersions", []):
            raise RuntimeFailure("지원하는 MCP 버전이 없습니다.")
    except RpcError as error:
        if error.error.get("code") not in {-32601, -32002}:
            raise
        client.legacy_mcp = True
        info = client.request(
            run,
            "initialize",
            {
                "protocolVersion": "2025-11-25",
                "capabilities": {},
                "clientInfo": {"name": "Agent Lens", "version": "0.9.0"},
            },
        )
        if info.get("protocolVersion") != "2025-11-25":
            raise RuntimeFailure("지원하지 않는 이전 MCP 버전입니다.")
        client.notify(run, "notifications/initialized")
    response = client.request(run, "tools/list", mcp_params(client))
    if response.get("nextCursor"):
        raise RuntimeFailure(
            "이 학습용 어댑터는 도구 목록 한 페이지를 지원합니다. 서버 도구 범위를 줄이세요."
        )
    prefix = config.get("name", "external")
    if not re.fullmatch(r"[a-zA-Z][a-zA-Z0-9_]{0,24}", prefix):
        raise ValueError("MCP 서버 이름은 짧은 영문 식별자를 사용하세요.")
    exposed = []
    allowed = config.get("allow_tools")
    read_only = config.get("read_only_tools", [])
    if not isinstance(read_only, list) or not all(
        isinstance(name, str) for name in read_only
    ):
        raise ValueError(
            "read_only_tools는 호스트가 읽기·계산 전용으로 지정한 도구 이름 목록이어야 합니다."
        )
    run.mcp_read_only_tools = set()
    if allowed is not None and (
        not isinstance(allowed, list)
        or not all(isinstance(name, str) for name in allowed)
    ):
        raise ValueError("allow_tools는 서버 도구 이름의 목록이어야 합니다.")
    policy = "allow_tools"
    if allowed is None:
        # 허용 목록이 없으면 서버가 광고한 도구를 자동으로 공개하지 않는다(기본 거부).
        # 서버 쪽 도구 목록이 늘어나도 호스트가 명시하지 않은 도구는 모델에 보이지 않는다.
        policy = "deny_without_allow_tools"
        allowed = []
        run.emit(
            "mcp.policy",
            "MCP 허용 목록 없음 · 기본 거부",
            "integrations.json의 mcp 프로필에 allow_tools가 없습니다. 서버가 광고한 도구를 자동으로 공개하지 않습니다. 공개할 원본 도구 이름을 allow_tools에 적고, 쓰기 권한이 꺼진 실행에서도 쓰려면 read_only_tools에도 적으세요.",
            category="integrations",
            actor="validator",
            input={"server": prefix, "advertised": [t.get("name") for t in response.get("tools", [])]},
            output={"policy": policy, "exposed": []},
        )
    writes_allowed = bool(run.features.get("writes"))
    advertised = [t.get("name", "") for t in response.get("tools", [])]
    duplicates = sorted({n for n in advertised if advertised.count(n) > 1})
    if duplicates:
        raise RuntimeFailure(
            "MCP 서버가 같은 이름의 도구를 두 번 광고했습니다: " + ", ".join(duplicates)
        )
    for tool in response.get("tools", []):
        remote = tool.get("name", "")
        if not writes_allowed and remote not in read_only:
            # 계획 모드는 쓰기 권한을 끈다. 쓰기 권한이 꺼진 다른 모드에서도 같은 기준을 적용해
            # 내장 write_file만 숨기고 외부 쓰기 도구는 노출하는 불일치를 막는다.
            reason = (
                "plan_requires_host_read_only"
                if run.mode == "plan"
                else "writes_off_requires_host_read_only"
            )
            run.emit(
                "mcp.tool.filtered",
                "계획 모드에서 외부 도구 제외"
                if run.mode == "plan"
                else "쓰기 권한이 꺼진 실행에서 외부 도구 제외",
                "호스트 설정의 read_only_tools에 없는 외부 도구입니다. 서버의 readOnlyHint만으로 권한을 부여하지 않습니다. 쓰기 권한을 켜거나 서버 구현을 확인한 뒤 read_only_tools에 등록하세요.",
                category="integrations",
                actor="validator",
                input=tool,
                output={"exposed": False, "reason": reason},
            )
            continue
        if remote not in allowed:
            run.emit(
                "mcp.tool.filtered",
                "MCP 도구 공개 범위에서 제외",
                "서버가 도구를 제공해도 하네스의 허용 목록에 없으면 모델에 공개하거나 실행하지 않습니다.",
                category="integrations",
                actor="mcp",
                input=tool,
                output={"exposed": False, "reason": "allow_tools"},
            )
            continue
        name = "mcp_" + prefix + "_" + remote
        schema = tool.get("inputSchema", {})
        if (
            not re.fullmatch(r"[a-zA-Z][a-zA-Z0-9_-]{0,63}", name)
            or schema.get("type") != "object"
        ):
            raise RuntimeFailure("지원하지 않는 MCP 도구 이름·schema입니다.")
        if any(
            v.get("type") not in {"string", "integer", "number", "boolean"}
            for v in schema.get("properties", {}).values()
        ):
            raise RuntimeFailure(
                "학습용 검증기는 단순한 스칼라 인자 schema를 지원합니다. policy.py 검증기를 확장하세요."
            )
        mapped = {
            "type": "function",
            "function": {
                "name": name,
                "description": tool.get("description", remote),
                "parameters": schema,
            },
        }
        run.extra_tools.append(mapped)
        if remote in read_only:
            run.mcp_read_only_tools.add(name)
        run.tool_handlers[name] = functools.partial(
            _mcp_tool, client=client, remote=remote
        )
        exposed.append(name)
        run.emit(
            "mcp.schema",
            "MCP 도구를 모델용 schema로 연결",
            "서버의 inputSchema를 function.parameters로 매핑하고 충돌을 피할 접두부를 붙였습니다. 아직 도구를 실행한 것은 아닙니다.",
            category="integrations",
            actor="mcp",
            input=tool,
            output=mapped,
        )
    run.integration_info.append(
        {
            "protocol": "mcp",
            "server": prefix,
            "pid": client.process.pid,
            "version": "2025-11-25"
            if getattr(client, "legacy_mcp", False)
            else MCP_VERSION,
            "tools": exposed,
            "policy": policy,
            "allow_tools": list(allowed),
            "read_only_tools": list(read_only),
            "discovery": info,
        }
    )

def prepare_lsp(run, config, workspace):
    client = client_for(config, "lsp", workspace)
    client.start(run)
    root = workspace.as_uri()
    if getattr(client, "initialized_pid", None) != client.process.pid:
        info = client.request(
            run,
            "initialize",
            {
                "processId": os.getpid(),
                "rootUri": root,
                "workspaceFolders": [{"uri": root, "name": "Agent Lens workspace"}],
                "capabilities": {
                    "textDocument": {"publishDiagnostics": {"versionSupport": True}}
                },
                "clientInfo": {"name": "Agent Lens", "version": "0.9.0"},
            },
        )
        client.notify(run, "initialized")
        client.notify(
            run,
            "workspace/didChangeConfiguration",
            {
                "settings": {
                    "pylsp": {
                        "plugins": {
                            "pyflakes": {"enabled": True},
                            "pycodestyle": {"enabled": False},
                            "mccabe": {"enabled": False},
                            "pydocstyle": {"enabled": False},
                            "pylint": {"enabled": False},
                        }
                    }
                }
            },
        )
        client.initialized_pid = client.process.pid
        client.documents = {}
        client.lsp_info = info
    for name, description, properties in [
        (
            "lsp_diagnostics",
            "Get actual Python language-server diagnostics. Use locations.line_1based for user-facing line numbers; raw diagnostics.range is zero-based.",
            {"path": {"type": "string"}},
        ),
        (
            "lsp_symbols",
            "Get document symbols from the actual language server.",
            {"path": {"type": "string"}},
        ),
        (
            "lsp_definition",
            "Get definitions from the language server. line and character are zero-based; character uses UTF-16 units.",
            {
                "path": {"type": "string"},
                "line": {"type": "integer"},
                "character": {"type": "integer"},
            },
        ),
    ]:
        run.extra_tools.append(
            {
                "type": "function",
                "function": {
                    "name": name,
                    "description": description,
                    "parameters": {
                        "type": "object",
                        "properties": properties,
                        "required": list(properties),
                        "additionalProperties": False,
                    },
                },
            }
        )
        run.tool_handlers[name] = functools.partial(
            _lsp_tool, client=client, operation=name
        )
    run.integration_info.append(
        {
            "protocol": "lsp",
            "server": config.get("name", "language-server"),
            "pid": client.process.pid,
            "tools": ["lsp_diagnostics", "lsp_symbols", "lsp_definition"],
            "capabilities": client.lsp_info,
        }
    )

def search_text(ctx, query, path="."):
    if not query or len(query) > 200:
        raise ValueError("검색어를 1~200자로 입력하세요.")
    target = workspace_path(ctx.workspace, path)
    if not target.exists():
        raise ValueError("검색할 파일이나 폴더가 없습니다.")
    candidates = [target] if target.is_file() else sorted(target.rglob("*"))
    matches = []
    scanned = 0
    total = 0
    limited = False
    for file in candidates:
        if (
            not file.is_file()
            or not file.resolve().is_relative_to(ctx.workspace)
            or file.suffix not in {".md", ".txt", ".py", ".json"}
            or file.stat().st_size > 65536
        ):
            continue
        if scanned >= 50 or total + file.stat().st_size > 524288:
            limited = True
            break
        relative = file.relative_to(ctx.workspace).as_posix()
        text = ctx.read(relative)
        scanned += 1
        total += file.stat().st_size
        for number, line in enumerate(text.splitlines(), 1):
            if query.casefold() in line.casefold():
                matches.append({"path": relative, "line": number, "text": line[:500]})
            if len(matches) >= 30:
                limited = True
                break
        if limited:
            break
    return ctx.finish(
        {
            "query": query,
            "matches": matches,
            "files_scanned": scanned,
            "scanned_bytes": total,
            "limited": limited,
        }
    )

def set_plan(ctx, steps):
    lines = [line.strip() for line in steps.splitlines() if line.strip()]
    if not 1 <= len(lines) <= 12 or any(len(line) > 300 for line in lines):
        raise ValueError("계획은 1~12줄, 한 줄 300자 이내로 작성하세요.")
    ctx.run.plan = [{"text": line, "status": "pending"} for line in lines]
    return ctx.finish({"plan": ctx.run.plan, "verified_work": False})

def prepare(run, harness):
    from .files import read_traced

    config = {}
    if run.mode in {"deep", "team"}:
        config = json.loads(
            read_traced(
                run,
                harness.workspace / "agents.json",
                "context",
                reason="선택한 모드의 예산·역할·권한을 실제 파일에서 읽습니다.",
            )
        )
    if run.mode == "plan":
        run.features["writes"] = False
        run.features["planning"] = run.features["tools"]
        run.role_instructions += "\nYou are in plan-only mode. Inspect available evidence and provide an actionable plan. Do not modify files or claim implementation. Use planning tools when available.\n"
    if run.mode == "deep":
        profile = config["deep"]
        run.max_model_calls = bounded(
            profile["max_model_calls"], 2, 16, "집중 모드 호출 예산"
        )
        run.review_instruction = profile["review_instruction"]
        if (
            not isinstance(run.review_instruction, str)
            or not 1 <= len(run.review_instruction) <= 2000
        ):
            raise ValueError("점검 지침은 1~2000자입니다.")
        run.role_instructions += "\nWork through this request carefully using tools. Before finalizing, the harness will request one additional review against actual evidence.\n"
    if run.mode == "team":
        if not run.features["tools"]:
            raise ValueError("하위 에이전트 모드는 도구 연결이 필요합니다.")
        team = config["team"]
        bounded(team["max_workers"], 1, 3, "동시 작업자 수")
        bounded(team["child_max_model_calls"], 1, 8, "하위 호출 예산")
        profiles = team["profiles"]
        if not isinstance(profiles, dict) or not 1 <= len(profiles) <= 4:
            raise ValueError("하위 역할은 1~4개입니다.")
        for key, profile in profiles.items():
            if not isinstance(key, str) or not key.isidentifier() or len(key) > 30:
                raise ValueError("역할 ID는 짧은 식별자로 작성하세요.")
            for field in ("label", "description", "instruction"):
                if (
                    not isinstance(profile.get(field), str)
                    or not 1 <= len(profile[field]) <= 2000
                ):
                    raise ValueError(
                        "역할의 label·description·instruction을 확인하세요."
                    )
            if (
                not isinstance(profile.get("tools"), list)
                or set(profile["tools"]) - READ_TOOLS
            ):
                raise ValueError(
                    "하위 에이전트는 지정한 읽기·검색·검사·계산 도구만 지원합니다."
                )
        public = [
            {
                "id": key,
                "label": p["label"],
                "description": p["description"],
                "tools": p["tools"],
            }
            for key, p in profiles.items()
        ]
        run.extra_tools.append(
            {
                "type": "function",
                "function": {
                    "name": "delegate_tasks",
                    "description": "Delegate independent tasks to real subagents. tasks_json is a JSON string array of 1 to 3 objects with profile and task. Profiles: "
                    + json.dumps(public, ensure_ascii=False),
                    "parameters": {
                        "type": "object",
                        "properties": {"tasks_json": {"type": "string"}},
                        "required": ["tasks_json"],
                        "additionalProperties": False,
                    },
                },
            }
        )
        run.tool_handlers["delegate_tasks"] = functools.partial(
            delegate_tasks, harness=harness, config=team
        )
        run.role_instructions += '\nYou are the main agent. Call delegate_tasks once to give independent, clearly scoped tasks to subagents using the listed profiles. Read their actual results before synthesizing your answer. tasks_json must be a JSON string array such as [{"profile":"explore","task":"read the requested document"},{"profile":"oracle","task":"check the requested document"}].\n'
        if not any(item["tool"] == "delegate_tasks" for item in run.requirements):
            run.requirements.append({"tool": "delegate_tasks", "arguments": {}})

def list_files(ctx):
    files = [
        path.relative_to(ctx.workspace).as_posix()
        for path in ctx.workspace.rglob("*")
        if path.is_file() and path.resolve().is_relative_to(ctx.workspace.resolve())
    ]
    return ctx.finish({"files": sorted(files)[:200]})

def read_file(ctx, path):
    canonical = (
        workspace_path(ctx.workspace, path).relative_to(ctx.workspace).as_posix()
    )
    return ctx.finish({"path": canonical, "content": ctx.read(path)})

def load_skill(ctx, name):
    selected = next((skill for skill in ctx.catalog if skill["name"] == name), None)
    if selected is None:
        raise ValueError("목록에 없는 스킬입니다.")
    instructions = ctx.read(selected["path"], category="skills")
    ctx.active_skills.add(name)
    return ctx.finish({"name": name, "instructions": instructions})

def write_file(ctx, path, content):
    if len(content.encode("utf-8")) > 65536:
        raise ValueError("파일 쓰기는 64 KiB까지 허용합니다.")
    target = workspace_path(ctx.workspace, path)
    before = ctx.read(path, required=False)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8", newline="")
    return ctx.finish(
        {
            "path": target.relative_to(ctx.workspace).as_posix(),
            "written_bytes": len(content.encode("utf-8")),
            "before": before,
            "after": content,
            "requires_check": True,
        }
    )

def check_file(ctx, path):
    text = ctx.read(path)
    target = workspace_path(ctx.workspace, path)
    canonical = target.relative_to(ctx.workspace).as_posix()
    # 검사기는 모델이 적은 문자열이 아니라 실제로 읽은 파일(정규화 경로)의 확장자로 고른다.
    # 'data/x.json\\'·심볼릭 링크 별칭·대소문자 변형으로 JSON 검사를 비껴가지 못하게 한다.
    suffix = target.suffix.lower()
    parsed = None
    try:
        if suffix == ".py":
            compile(ast.parse(text, filename=canonical), canonical, "exec")
            checker = "ast.parse + compile (Python 구문 확인; 프로그램 실행 없음)"
        elif suffix == ".json":
            parsed = json.loads(text)
            checker = "json.loads (JSON 구문 분석)"
        else:
            if not text.strip():
                raise ValueError("파일 내용이 비어 있습니다.")
            checker = "non-empty text"
        result = {"path": canonical, "passed": True, "checker": checker}
        if suffix == ".json":
            result["json_value"] = parsed
    except (SyntaxError, ValueError) as error:
        result = {"path": canonical, "passed": False, "error": str(error)}
    return ctx.finish(result)

def search_text(ctx, query, path="."):
    if not query or len(query) > 200:
        raise ValueError("검색어를 1~200자로 입력하세요.")
    target = workspace_path(ctx.workspace, path)
    if not target.exists():
        raise ValueError("검색할 파일이나 폴더가 없습니다.")
    candidates = [target] if target.is_file() else sorted(target.rglob("*"))
    matches = []
    scanned = 0
    total = 0
    limited = False
    for file in candidates:
        if (
            not file.is_file()
            or not file.resolve().is_relative_to(ctx.workspace)
            or file.suffix not in {".md", ".txt", ".py", ".json"}
            or file.stat().st_size > 65536
        ):
            continue
        if scanned >= 50 or total + file.stat().st_size > 524288:
            limited = True
            break
        relative = file.relative_to(ctx.workspace).as_posix()
        text = ctx.read(relative)
        scanned += 1
        total += file.stat().st_size
        for number, line in enumerate(text.splitlines(), 1):
            if query.casefold() in line.casefold():
                matches.append({"path": relative, "line": number, "text": line[:500]})
            if len(matches) >= 30:
                limited = True
                break
        if limited:
            break
    return ctx.finish(
        {
            "query": query,
            "matches": matches,
            "files_scanned": scanned,
            "scanned_bytes": total,
            "limited": limited,
        }
    )

def set_plan(ctx, steps):
    lines = [line.strip() for line in steps.splitlines() if line.strip()]
    if not 1 <= len(lines) <= 12 or any(len(line) > 300 for line in lines):
        raise ValueError("계획은 1~12줄, 한 줄 300자 이내로 작성하세요.")
    ctx.run.plan = [{"text": line, "status": "pending"} for line in lines]
    return ctx.finish({"plan": ctx.run.plan, "verified_work": False})

def complete_plan_step(ctx, index):
    if not 1 <= index <= len(ctx.run.plan):
        raise ValueError("등록한 계획 항목의 번호를 사용하세요.")
    ctx.run.plan[index - 1]["status"] = "done"
    return ctx.finish({"plan": ctx.run.plan, "verified_work": False})
